#include <iostream>
#include <string>
using namespace std;

int main() {
    int age = 8;
    string category;
    int price;

    if (age < 5) {
        category = "Infant";
        price = 0;
    } else if (age < 13) {
        category = "Child";
        price = 120;
    } else {
        category = "Adult";
        price = 250;
    }

    cout << category << ": " << price << endl;
    return 0;
}

